/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Basic, Float, MatrixSymbol, Mul, Pow, Rational, Sym, add, attrprint, dotnode, dotprint, pprintUseUnicode, purestr } from '../../src';
import { sympyStr, text } from '../sympy-str';

describe("doctests of sympy.printing.dot", () => {
  it("print(dotprint(x+2)) # doctest: +NORMALIZE_WHITESPACE", () => {
    const x = new Sym('x');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(dotprint(add(Rational.of(2n, 1n, { gcd: 1n }), x), {}), true)).toBe('digraph{ # Graph style "ordering"="out" "rankdir"="TD" ######### # Nodes # ######### "Add(Integer(2), Symbol(\'x\'))_()" ["color"="black", "label"="Add", "shape"="ellipse"]; "Integer(2)_(0,)" ["color"="black", "label"="2", "shape"="ellipse"]; "Symbol(\'x\')_(1,)" ["color"="black", "label"="x", "shape"="ellipse"]; ######### # Edges # ######### "Add(Integer(2), Symbol(\'x\'))_()" -> "Integer(2)_(0,)"; "Add(Integer(2), Symbol(\'x\'))_()" -> "Symbol(\'x\')_(1,)"; }');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("eval(code) == Symbol('x')", () => {
    const x = new Sym('x');
    expect(sympyStr(x.equals(x))).toBe('True');
  });
  it("eval(code) == MatrixSymbol('x', 2, 2)", () => {
    expect(sympyStr(new MatrixSymbol('x', Rational.of(2n, 1n, { gcd: 1n }), Rational.of(2n, 1n, { gcd: 1n })).equals(new MatrixSymbol('x', Rational.of(2n, 1n, { gcd: 1n }), Rational.of(2n, 1n, { gcd: 1n }))))).toBe('True');
  });
  it("print(attrprint({'color': 'blue', 'shape': 'ellipse'}))", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(attrprint(new Map([['color', 'blue'], ['shape', 'ellipse']])))).toBe('"color"="blue", "shape"="ellipse"');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("print(dotnode(x))", () => {
    const x = new Sym('x');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(dotnode(x))).toBe('"Symbol(\'x\')_()" ["color"="black", "label"="x", "shape"="ellipse"];');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("purestr(Float(2))", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(purestr(new Float({ man: 1n, exp: 1n }, 53)))).toBe('Float(\'2.0\', precision=53)');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  // a primitive result that no library call returned
  //   purestr(Float(2), with_args=True)
  //   => ("Float('2.0', precision=53)", ())
  it.todo("purestr(Float(2), with_args=True)");
  // a primitive result that no library call returned
  //   purestr(MatrixSymbol('x', 2, 2), with_args=True)
  //   => ("MatrixSymbol(Str('x'), Integer(2), Integer(2))", ("Str('x')", 'Integer(2)', 'Integer(2)'))
  it.todo("purestr(MatrixSymbol('x', 2, 2), with_args=True)");
  // a primitive result that no library call returned
  //   styleof(Basic(S(1)), styles)
  //   => {'color': 'blue', 'shape': 'ellipse'}
  it.todo("styleof(Basic(S(1)), styles)");
  // a primitive result that no library call returned
  //   styleof(x + 1, styles)  # this is an Expr
  //   => {'color': 'black', 'shape': 'ellipse'}
  it.todo("styleof(x + 1, styles)  # this is an Expr");
  it("code", () => {
    const x = new Sym('x');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(purestr(x))).toBe('Symbol(\'x\')');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("code (2)", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(purestr(new MatrixSymbol('x', Rational.of(2n, 1n, { gcd: 1n }), Rational.of(2n, 1n, { gcd: 1n }))))).toBe('MatrixSymbol(Str(\'x\'), Integer(2), Integer(2))');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
});

